import { API_BASE_URL } from '../config/api';

export interface TimeSlot {
  id: string;
  startsAt: string;
  available: boolean;
}

export async function fetchSlots(date: string): Promise<TimeSlot[]> {
  const response = await fetch(`${API_BASE_URL}/slots?date=${date}`);
  if (!response.ok) throw new Error(`Slots failed with status ${response.status}`);
  return (await response.json()) as TimeSlot[];
}

export async function bookSlot(slotId: string): Promise<{ bookingId: string }> {
  const response = await fetch(`${API_BASE_URL}/slots/${slotId}/book`, { method: 'POST' });
  if (!response.ok) throw new Error(`Booking failed with status ${response.status}`);
  return (await response.json()) as { bookingId: string };
}

import { useCallback, useEffect, useMemo, useState } from 'react';
import { View, Text, TouchableOpacity, ScrollView, StyleSheet, SafeAreaView, ActivityIndicator } from 'react-native';
import { fetchSlots, bookSlot, type TimeSlot } from '../services/booking';

const colors = {
  accent: '#f05039',
  bg: '#0f120e',
  surface: '#1a1f1a',
  textMuted: '#a8ada6',
  text: '#f5f5f0',
  muted: '#8a8f8a',
  success: '#4ade80',
  danger: '#ff6b5e',
}

const DAYS = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri'];

export function BookingScreen(): JSX.Element {
  const [day, setDay] = useState(DAYS[0]);
  const [slots, setSlots] = useState<TimeSlot[]>([]);
  const [selected, setSelected] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [confirmed, setConfirmed] = useState<string | null>(null);

    const load = useCallback(async () => {
    setLoading(true);
    setError(null);
    setSelected(null);
    try {
      const data = await fetchSlots(day);
      setSlots(data);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to load slots.');
    } finally {
      setLoading(false);
    }
  }, [day]);

  useEffect(() => {
    void load();
  }, [load]);

  const book = useCallback(async () => {
    if (!selected) return;
    try {
      const { bookingId } = await bookSlot(selected);
      setConfirmed(bookingId);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Booking failed.');
    }
  }, [selected]);

  const timeLabel = useMemo(() => (slot: TimeSlot) => new Date(slot.startsAt).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }), []);

  return (
    <SafeAreaView style={styles.safe}>
      <View style={styles.days}>
        {DAYS.map(d => (
          <TouchableOpacity key={d} style={[styles.day, day === d && styles.dayActive]} onPress={() => setDay(d)} accessibilityRole="button">
            <Text style={[styles.dayText, day === d && styles.dayTextActive]}>{d}</Text>
          </TouchableOpacity>
        ))}
      </View>
      {loading && <ActivityIndicator color="{colors.accent}" style={styles.center} />}
      {!loading && error && <Text style={styles.error}>{error}</Text>}
      {!loading && !error && slots.length === 0 && <Text style={styles.empty}>No availability this day.</Text>}
      {!loading && !error && slots.length > 0 && (
        <ScrollView contentContainerStyle={styles.grid}>
          {slots.map(slot => {
            const isSelected = selected === slot.id;
            return (
              <TouchableOpacity
                key={slot.id}
                disabled={!slot.available}
                style={[styles.slot, !slot.available && styles.slotFull, isSelected && styles.slotSelected]}
                onPress={() => setSelected(slot.id)}
                accessibilityRole="button"
                accessibilityLabel={`${timeLabel(slot)} ${slot.available ? 'available' : 'full'}`}
              >
                <Text style={[styles.slotText, !slot.available && styles.slotTextFull]}>{timeLabel(slot)}</Text>
              </TouchableOpacity>
            );
          })}
          {confirmed ? (
            <Text style={styles.confirm}>Booked! Confirmation #{confirmed}</Text>
          ) : (
            <TouchableOpacity style={[styles.primary, !selected && styles.disabled]} disabled={!selected} onPress={book} accessibilityRole="button">
              <Text style={styles.primaryText}>Confirm booking</Text>
            </TouchableOpacity>
          )}
        </ScrollView>
      )}
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  safe: { flex: 1, backgroundColor: colors.bg },
  days: { flexDirection: 'row', gap: 8, padding: 16 },
  day: { flex: 1, alignItems: 'center', backgroundColor: colors.surface, borderRadius: 6, paddingVertical: 10 },
  dayActive: { backgroundColor: colors.accent },
  dayText: { color: colors.textMuted },
  dayTextActive: { color: colors.bg, fontWeight: '700' },
  grid: { flexDirection: 'row', flexWrap: 'wrap', gap: 10, padding: 16 },
  slot: { width: '30%', backgroundColor: colors.surface, borderRadius: 8, paddingVertical: 14, alignItems: 'center' },
  slotSelected: { borderWidth: 2, borderColor: colors.accent },
  slotFull: { opacity: 0.35 },
  slotText: { color: colors.text },
  slotTextFull: { color: colors.muted },
  primary: { width: '100%', backgroundColor: colors.accent, borderRadius: 6, paddingVertical: 14, alignItems: 'center', marginTop: 8 },
  primaryText: { color: colors.bg, fontWeight: '700' },
  disabled: { opacity: 0.5 },
  confirm: { width: '100%', color: colors.success, textAlign: 'center', marginTop: 8 },
  center: { marginTop: 40 },
  error: { color: colors.danger, textAlign: 'center', marginTop: 24, paddingHorizontal: 16 },
  empty: { color: colors.muted, textAlign: 'center', marginTop: 24 },
});
